def solve_p3_modular():
    solutions = []
    # Candidates for a, b congruent to 2 mod 3 up to 20: 2, 5, 8, 11, 14, 17, 20
    candidates = [i for i in range(1, 21) if i % 3 == 2]

    for a in candidates:
        for b in candidates:
            if a > b:
                continue
            if a == b:
                # Check a=b case: 2a^2 = 3^x. This requires 3^x to be even, impossible for x>=1.
                # However, we stick to the check for completeness.
                pass

            # Check condition 1: a^2 + b = 3^x
            val1 = a**2 + b
            is_pow3_1 = False
            while val1 > 0:
                if val1 % 3 == 0:
                    val1 //= 3
                    is_pow3_1 = True
                else:
                    break

            if is_pow3_1 and val1 == 1:
                # Condition 1 satisfied. Check Condition 2: b^2 + a = 3^y
                val2 = b**2 + a
                is_pow3_2 = False
                while val2 > 0:
                    if val2 % 3 == 0:
                        val2 //= 3
                        is_pow3_2 = True
                    else:
                        break

                if is_pow3_2 and val2 == 1:
                    solutions.append((a, b))

    print(f"Solutions found (a, b) where a, b <= 20 and a, b == 2 mod 3: {solutions}")

